class RangeChecker {
    const int lower, upper;
public:
    RangeChecker(int l, int u) : lower(l), upper(u) {}

    // Overloaded function-call operator
    bool operator()(int val) const {
        return val >= lower && val <= upper;
    }
};

// Usage Example:
// RangeChecker predicate(10, 20);
// bool is_valid = predicate(15);

class Counter {
    int count = 0;
public:
    int operator()() {
        return ++count;
    }
};
